-- =============================================================
-- Ağustos paketleme verisi sıfırdan yüklendi (personel bazlı)
--
-- Kullanıcı Ağustos'un tamamını Excel olarak verdi (1–22 Ağustos, 201
-- seans). Sistemdeki eksik/kısmi Ağustos kaydı silinip bu veri
-- yükleniyor. BUGÜN (24.08) korunuyor — o kayıtlar sistemden canlı
-- giriliyor ve stok hareketleri var.
--
-- TARİH DÜZELTMESİ: Excel'de Tarih kolonu bozuk (01/08 -> Ocak 8 olarak
-- okunmuş, US/EU format karışması). Gerçek tarih SessionID'den alındı
-- (PKT-YYYYMMDD). Başlangıç/bitiş saatleri hücrelerin saat kısmından.
--
-- Bu yükleme yalnızca pack_events'e yazar; stock_movements OLUŞTURMAZ.
-- Sebep: mamül stok ayrı yönetiliyor (sayım) ve geçmiş paketleme zaten
-- stok hareketi üretmemişti; buradaki amaç personel/süre analizi.
-- =============================================================

DO $$
BEGIN
  -- 1–23 Ağustos arası eski kayıtları temizle, bugünü (24.08) koru
  DELETE FROM pack_events
  WHERE (start_time AT TIME ZONE 'Europe/Istanbul')::date >= '2026-08-01'
    AND (start_time AT TIME ZONE 'Europe/Istanbul')::date < '2026-08-24';
END $$;

